"""Facts about the lab world: where things are. You do not edit this file.

All positions are in the WORLD frame (Gazebo's frame), in metres.
The robot starts at SPAWN, facing +x (yaw 0). The odom frame starts where
the robot starts, so

        world position = odom position + (SPAWN_X, SPAWN_Y)

(no rotation is needed because the spawn yaw is 0). Lab 2 uses this.
"""

import math
import os
import xml.etree.ElementTree as ET

SPAWN_X, SPAWN_Y, SPAWN_YAW = -4.0, 0.5, 0.0

# Lab 2: the three cylinders (radius 0.12 m). Same numbers as worlds/ee414_house.sdf.
CYLINDER_RADIUS = 0.12
CYLINDERS = {
    'red': (-3.00, 3.60),
    'green': (-1.00, 2.00),
    'blue': (-4.30, 2.40),
}

# Lab 3: the orange box (centre, size) that blocks the way to the goal.
BUG_BOX = ((-2.40, 0.45), (0.40, 1.00))

# The rooms, as rectangles (xmin, xmax, ymin, ymax). Used to count which
# rooms a wandering robot has visited.
ROOMS = {
    'living room': (-5.10, -0.05, -0.15, 5.30),
    'kitchen': (-0.05, 2.30, 0.90, 5.30),
    'entrance': (-0.05, 2.30, -0.15, 0.90),
    'big room': (2.30, 7.50, -0.15, 5.30),
    'north-west room': (-7.50, -5.10, 0.90, 5.30),
    'south-west room': (-7.50, -5.10, -3.90, 0.90),
    'south-east room': (4.90, 7.50, -5.30, -0.15),
}


def odom_to_world(x, y):
    """A point in the odom frame -> the same point in the world frame."""
    c, s = math.cos(SPAWN_YAW), math.sin(SPAWN_YAW)
    return SPAWN_X + c * x - s * y, SPAWN_Y + s * x + c * y


def world_to_odom(x, y):
    """A point in the world frame -> the same point in the odom frame."""
    dx, dy = x - SPAWN_X, y - SPAWN_Y
    c, s = math.cos(SPAWN_YAW), math.sin(SPAWN_YAW)
    return c * dx + s * dy, -s * dx + c * dy


def room_of(wx, wy):
    """Name of the room that contains the world point (wx, wy)."""
    for name, (x0, x1, y0, y1) in ROOMS.items():
        if x0 <= wx <= x1 and y0 <= wy <= y1:
            return name
    return 'outside'


# ---- drawing the floor plan (for the trajectory pictures) ----------------

def _pose(el):
    t = el.findtext('pose')
    v = [float(x) for x in t.split()] if t else [0.0] * 6
    return v[0], v[1], v[2], v[5]


def _compose(a, b):
    x, y, z, t = a
    bx, by, bz, bt = b
    return (x + bx * math.cos(t) - by * math.sin(t),
            y + bx * math.sin(t) + by * math.cos(t), z + bz, t + bt)


def house_walls(height=0.17):
    """What the laser plane (17 cm high) cuts in the house: a list of
    4-corner polygons (walls, furniture) and a list of (x, y, radius)
    circles (table legs), in the world frame."""
    try:
        from ament_index_python.packages import get_package_share_directory
        sdf = os.path.join(get_package_share_directory('turtlebot3_gazebo'),
                           'models', 'turtlebot3_house', 'model.sdf')
        root = ET.parse(sdf).getroot().find('model')
    except Exception:
        return [], []
    polys, circles = [], []

    def walk(model, base):
        mp = _compose(base, _pose(model))
        for link in model.findall('link'):
            lp = _compose(mp, _pose(link))
            for col in link.findall('collision'):
                cp = _compose(lp, _pose(col))
                cyl = col.find('geometry/cylinder')
                if cyl is not None:
                    half = float(cyl.findtext('length')) / 2
                    if cp[2] - half <= height <= cp[2] + half:
                        circles.append((cp[0], cp[1], float(cyl.findtext('radius'))))
                    continue
                box = col.find('geometry/box')
                if box is None:
                    continue
                sx, sy, sz = (float(v) for v in box.findtext('size').split())
                if not (cp[2] - sz / 2 <= height <= cp[2] + sz / 2):
                    continue
                pts = []
                for dx, dy in ((-1, -1), (1, -1), (1, 1), (-1, 1)):
                    px, py, _, _ = _compose(cp, (dx * sx / 2, dy * sy / 2, 0, 0))
                    pts.append((px, py))
                polys.append(pts)
        for child in model.findall('model'):
            walk(child, mp)

    walk(root, (0.0, 0.0, 0.0, 0.0))
    return polys, circles


def draw_house(ax):
    """Draw walls, the cylinders, the box and the spawn point on a matplotlib axis."""
    from matplotlib.patches import Circle, Polygon, Rectangle
    polys, circles = house_walls()
    for pts in polys:
        ax.add_patch(Polygon(pts, color='0.25'))
    for x, y, r in circles:
        ax.add_patch(Circle((x, y), max(r, 0.04), color='0.25'))
    ax.add_patch(Rectangle((0.55, -0.225), 1.10, 0.15, color='saddlebrown'))   # front door
    for name, (cx, cy) in CYLINDERS.items():
        ax.add_patch(Circle((cx, cy), CYLINDER_RADIUS, color=name))
    (bx, by), (sx, sy) = BUG_BOX
    ax.add_patch(Rectangle((bx - sx / 2, by - sy / 2), sx, sy, color='orange'))
    ax.plot(SPAWN_X, SPAWN_Y, 'k*', ms=12, label='start')
    ax.set_aspect('equal')
    ax.set_xlim(-8.0, 8.0)
    ax.set_ylim(-5.8, 5.8)
    ax.grid(True, alpha=0.3)
    ax.set_xlabel('world x (m)')
    ax.set_ylabel('world y (m)')
